// Dynamic Webhook Lead/Order Normalizer (Reads real POST body or query parameters)
return $input.all().map((item) => {
  const raw = item.json.body || item.json.query || item.json || {};
  const amountNum = parseFloat(String(raw.amount || raw.total || raw.Deal_Amount || '1250.00').replace(/[^0-9.]/g, '')) || 1250.00;
  const isVip = amountNum >= 1000;

  return {
    json: {
      Order_ID: raw.order_id || raw.id || raw.Order_ID || 'ORD-2027-' + Math.floor(1000 + Math.random() * 9000),
      Client_Name: raw.name || raw.customer_name || raw.Client_Name || 'Apex Digital Agency',
      Client_Email: raw.email || raw.customer_email || raw.Client_Email || 'ops@apexdigital.io',
      Deal_Amount: '$' + amountNum.toLocaleString('en-US', { minimumFractionDigits: 2, maximumFractionDigits: 2 }),
      Amount_Numeric: amountNum,
      Is_VIP: isVip,
      Priority_Tier: isVip ? '🔥 VIP HIGH-TICKET (>= $1,000)' : '✓ Standard Order',
      Zapier_Fee_Saved: '$0.00 Task Fee (Hostinger KVM 1 Unlimited — Save $1,710/yr)'
    }
  };
});
